	"Jycn2gYBMeIGAQ/qBgUXHyMrLPIGBQUHCQ0N+gYBVGgBApIIEwIEBggKDA4CCAoICAgMCAYOBA6a" +
	"CBMBUkQEBQYADhIODg4pDgIGAQaiCBM28QAFAQCqUhYAVMIIEwEDBQcJCw0AAAAAAAAAAAAAAAA="

// SLIR is the compiled SLIR document this package installs, decoded once at
// package initialization. The slice is shared, so callers must not modify it.
var SLIR []byte

// init decodes the embedded document. A corrupt payload can only come from a
// hand-edited generated file, so it fails loudly rather than silently.
func init() {
	decoded, err := base64.StdEncoding.DecodeString(slirBase64)
	if err != nil {
		panic("slab: embedded SLIR payload is corrupt: " + err.Error())
	}
	SLIR = decoded
}

// KeySave is the canonical scene key of the authored `#save` node.
const KeySave = "col@0/row@0/#save/row@0"

// KeyReset is the canonical scene key of the authored `#reset` node.
const KeyReset = "col@0/row@0/#reset/row@0"

// KeySort is the canonical scene key of the authored `#sort` node.
const KeySort = "col@0/row@0/#sort/row@0"

// KeyStatus is the canonical scene key of the authored `#status` node.
const KeyStatus = "col@0/row@0/#status"

// KeyField is the canonical scene key of the authored `#field` node.
const KeyField = "col@0/#field"

// KeyPanel is the canonical scene key of the authored `#panel` node.
const KeyPanel = "col@0/#panel"

// ParamTitle is the SDP name of param `title` (text).
const ParamTitle = "title"

// ParamStatus is the SDP name of param `status` (text).
const ParamStatus = "status"

// ParamDraft is the SDP name of param `draft` (text).
const ParamDraft = "draft"

// ParamCompact is the SDP name of param `compact` (bool).
const ParamCompact = "compact"

// ParamEditing is the SDP name of param `editing` (bool).
const ParamEditing = "editing"

// SignalName is one authored signal name from the document's SIGN table.
type SignalName string

// SignalSave is the authored signal `save`; it carries no text payload.
const SignalSave SignalName = "save"

// SignalReset is the authored signal `reset`; it carries no text payload.
const SignalReset SignalName = "reset"

// SignalSort is the authored signal `sort`; it carries no text payload.
const SignalSort SignalName = "sort"

// SignalDraft is the authored signal `draft`; it carries a text payload.
const SignalDraft SignalName = "draft"

// SignalDraftSubmit is the authored signal `draft_submit`; it carries a text payload.
const SignalDraftSubmit SignalName = "draft_submit"

// Signal is one decoded emission of a signal this document declares.
type Signal struct {
	// Name is the authored signal name.
	Name SignalName
	// Text is the committed field text or final resize extent, and is empty for
	// signals that carry no text payload.
	Text string
	// Item is the innermost list item key, or empty outside a list.
	Item string
	// Meta is the input and source metadata captured at emission.
	Meta slab.SignalMeta
}

// DecodeSignals converts the ordered effect signals into typed values, keeping only
// the names this document declares and preserving emission order.
func DecodeSignals(effects slab.Effects) []Signal {
	out := make([]Signal, 0, len(effects.Signals))
	for _, raw := range effects.Signals {
		name := SignalName(raw.Name)
		switch name {
		case SignalSave, SignalReset, SignalSort, SignalDraft, SignalDraftSubmit:
		default:
			continue
		}
		out = append(out, Signal{Name: name, Text: raw.Text, Item: raw.Item, Meta: raw.Meta})
	}
	return out
}

// Doc is the typed wrapper over a session holding this document. Every setter
// routes through the Slab Drive Protocol, so the kernel stays the single owner of
// layout, hit testing, focus, and editing.
type Doc struct {
	// sess is the session the document was opened in.
	sess *slab.Session
}

// New installs the embedded document in sess and returns the typed wrapper. The
// document is already compiled, so the runtime never parses `.slab` text and no
// host filesystem is involved.
func New(ctx context.Context, sess *slab.Session) (*Doc, error) {
	if err := sess.OpenSLIR(ctx, SLIR, SourceName); err != nil {
		return nil, err
	}
	return &Doc{sess: sess}, nil
}

// Session returns the underlying session, the escape hatch for SDP methods this
// binding does not wrap.
func (d *Doc) Session() *slab.Session {
	return d.sess
}

// setParam writes one scalar param through the protocol's `param.set` method.
func (d *Doc) setParam(ctx context.Context, name string, value any) error {
	_, err := d.sess.Request(ctx, "param.set", map[string]any{"name": name, "value": value})
	return err
}

// SetTitle sets param `title` (text).
func (d *Doc) SetTitle(ctx context.Context, value string) error {
	return d.setParam(ctx, "title", value)
}

// SetStatus sets param `status` (text).
func (d *Doc) SetStatus(ctx context.Context, value string) error {
	return d.setParam(ctx, "status", value)
}

// SetDraft sets param `draft` (text).
func (d *Doc) SetDraft(ctx context.Context, value string) error {
	return d.setParam(ctx, "draft", value)
}

// SetCompact sets param `compact` (bool).
func (d *Doc) SetCompact(ctx context.Context, value bool) error {
	return d.setParam(ctx, "compact", value)
}

// SetEditing sets param `editing` (bool).
func (d *Doc) SetEditing(ctx context.Context, value bool) error {
	return d.setParam(ctx, "editing", value)
}
